-- LABELXR-REVIEW-RPC-v1
-- Atomic authenticated commands;caller owner,patch or IoU is never trusted.
BEGIN;
CREATE FUNCTION labelroom_private.review_need(ok boolean,detail text) RETURNS void LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION '%',detail USING ERRCODE='22023';END IF;END $$;
CREATE FUNCTION labelroom_private.review_utf16(s text) RETURNS integer[] LANGUAGE plpgsql IMMUTABLE STRICT SET search_path='' AS $$
DECLARE out integer[]:='{}';cp integer;i integer;BEGIN FOR i IN 1..length(s) LOOP cp:=ascii(substr(s,i,1));IF cp<65536 THEN out:=array_append(out,cp);ELSE cp:=cp-65536;out:=out||ARRAY[55296+cp/1024,56320+cp%1024];END IF;END LOOP;RETURN out;END $$;
CREATE FUNCTION labelroom_private.review_number(v jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path='' SET extra_float_digits=3 AS $$
DECLARE n float8;s text;e integer;parts text[];BEGIN
 PERFORM labelroom_private.review_need(jsonb_typeof(v)='number','Expected JSON number');n:=(v#>>'{}')::float8;PERFORM labelroom_private.review_need(n NOT IN ('Infinity'::float8,'-Infinity'::float8,'NaN'::float8),'Finite number required');IF n=0 THEN RETURN '0';END IF;s:=n::text;
 IF abs(n)>=0.000001 AND abs(n)<1e21 THEN s:=(s::numeric)::text;IF strpos(s,'.')>0 THEN s:=rtrim(rtrim(s,'0'),'.');END IF;
 ELSE parts:=string_to_array(lower(s),'e');IF cardinality(parts)=2 THEN e:=parts[2]::integer;s:=parts[1]||'e'||CASE WHEN e>=0 THEN '+' ELSE '-' END||abs(e)::text;END IF;END IF;RETURN s;END $$;
CREATE FUNCTION labelroom_private.review_canonical(v jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path='' AS $$
DECLARE kind text:=jsonb_typeof(v);result text;BEGIN
 IF kind='number' THEN RETURN labelroom_private.review_number(v);END IF;
 IF kind='array' THEN SELECT '['||coalesce(string_agg(labelroom_private.review_canonical(x.value),',' ORDER BY x.ord),'')||']' INTO result FROM jsonb_array_elements(v) WITH ORDINALITY x(value,ord);RETURN result;END IF;
 IF kind='object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(x.key)::text||':'||labelroom_private.review_canonical(x.value),',' ORDER BY labelroom_private.review_utf16(x.key)),'')||'}' INTO result FROM jsonb_each(v) x;RETURN result;END IF;RETURN v::text;END $$;
CREATE FUNCTION labelroom_private.review_hash(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path='' AS $$ SELECT encode(sha256(convert_to(labelroom_private.review_canonical(v),'UTF8')),'hex') $$;
CREATE FUNCTION labelroom_private.review_id(v jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE s text:=v#>>'{}';BEGIN PERFORM labelroom_private.review_need(jsonb_typeof(v)='string' AND cardinality(labelroom_private.review_utf16(s)) BETWEEN 1 AND 128 AND length(btrim(s,E' \t\n\r\v\f'||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'))>0,'Bounded nonempty identifier required');RETURN s;END $$;
CREATE FUNCTION labelroom_private.review_box(v jsonb) RETURNS float8[] LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE a float8[]:='{}';x jsonb;i integer;BEGIN
 PERFORM labelroom_private.review_need(jsonb_typeof(v)='array' AND jsonb_array_length(v)=10,'Cuboid must contain ten numbers');FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM labelroom_private.review_number(x);a:=array_append(a,(x#>>'{}')::float8);END LOOP;
 PERFORM labelroom_private.review_need(abs(a[1])<=250 AND abs(a[2])<=250 AND abs(a[3])<=250 AND abs(a[4])<=0.0001 AND abs(a[5])<=0.0001 AND abs(sqrt(a[4]^2+a[5]^2+a[6]^2+a[7]^2)-1)<=0.0001,'Cuboid centre or upright quaternion outside bounds');FOR i IN 8..10 LOOP PERFORM labelroom_private.review_need(a[i] BETWEEN 0.05 AND 50,'Cuboid dimensions outside bounds');END LOOP;RETURN a;END $$;
CREATE FUNCTION labelroom_private.review_iou(av jsonb,bv jsonb) RETURNS float8 LANGUAGE plpgsql IMMUTABLE SET search_path='' SET extra_float_digits=3 AS $$
DECLARE a float8[]:=labelroom_private.review_box(av);b float8[]:=labelroom_private.review_box(bv);ya float8:=2*atan2(a[6],a[7]);yb float8:=2*atan2(b[6],b[7]);ca float8:=cos(ya);sa float8:=sin(ya);cb float8:=cos(yb);sb float8:=sin(yb);dx float8:=b[1]-a[1];dy float8:=b[2]-a[2];dz float8:=b[3]-a[3];height float8;poly jsonb:='[]';next_poly jsonb;prev jsonb;cur jsonb;other jsonb;sx integer;sy integer;clip integer;axis integer;sign float8;half float8;x float8;y float8;dp float8;dc float8;t float8;cx float8;cy float8;twice_area float8:=0;vol float8;ceiling float8;i integer;
BEGIN
 height:=greatest(0,least(a[10]/2,dz+b[10]/2)-greatest(-a[10]/2,dz-b[10]/2));IF height=0 THEN RETURN 0;END IF;
 FOR i IN 1..4 LOOP sx:=CASE WHEN i IN (1,4) THEN -1 ELSE 1 END;sy:=CASE WHEN i IN (1,2) THEN -1 ELSE 1 END;x:=dx+cb*sx*b[8]/2-sb*sy*b[9]/2;y:=dy+sb*sx*b[8]/2+cb*sy*b[9]/2;poly:=poly||jsonb_build_array(jsonb_build_array(ca*x+sa*y,-sa*x+ca*y));END LOOP;
 FOR clip IN 1..4 LOOP IF jsonb_array_length(poly)=0 THEN RETURN 0;END IF;axis:=CASE WHEN clip<=2 THEN 0 ELSE 1 END;sign:=CASE WHEN clip IN (1,3) THEN 1 ELSE -1 END;half:=CASE WHEN axis=0 THEN a[8]/2 ELSE a[9]/2 END;next_poly:='[]';prev:=poly->(jsonb_array_length(poly)-1);dp:=half-sign*(prev->>axis)::float8;
 FOR cur IN SELECT value FROM jsonb_array_elements(poly) LOOP dc:=half-sign*(cur->>axis)::float8;IF (dp>=0)<>(dc>=0) THEN t:=dp/(dp-dc);cx:=(prev->>0)::float8+t*((cur->>0)::float8-(prev->>0)::float8);cy:=(prev->>1)::float8+t*((cur->>1)::float8-(prev->>1)::float8);IF axis=0 THEN cx:=sign*half;ELSE cy:=sign*half;END IF;next_poly:=next_poly||jsonb_build_array(jsonb_build_array(cx,cy));END IF;IF dc>=0 THEN next_poly:=next_poly||jsonb_build_array(cur);END IF;prev:=cur;dp:=dc;END LOOP;poly:=next_poly;END LOOP;
 IF jsonb_array_length(poly)<3 THEN RETURN 0;END IF;FOR i IN 0..jsonb_array_length(poly)-1 LOOP cur:=poly->i;other:=poly->((i+1)%jsonb_array_length(poly));twice_area:=twice_area+(cur->>0)::float8*(other->>1)::float8-(cur->>1)::float8*(other->>0)::float8;END LOOP;vol:=abs(twice_area)/2*height;ceiling:=least(a[8]*a[9]*a[10],b[8]*b[9]*b[10]);PERFORM labelroom_private.review_need(vol<=ceiling+0.000001,'Overlap numerical bound failed');vol:=least(ceiling,greatest(0,vol));RETURN least(1,greatest(0,vol/(a[8]*a[9]*a[10]+b[8]*b[9]*b[10]-vol)));END $$;
CREATE FUNCTION labelroom_private.review_fingerprint(p public.projects,doc jsonb,frame text,issue jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE ids text[];kind text:=issue->>'type';f jsonb;fid text;tracks jsonb:='[]';boxes jsonb;oid text;occ jsonb;val jsonb;BEGIN
 PERFORM labelroom_private.review_need(jsonb_typeof(issue)='object' AND (SELECT count(*) FROM jsonb_object_keys(issue))=2 AND issue ?& ARRAY['type','objectIds'] AND kind IN ('LOW_SUPPORT','DUPLICATE','DIMENSION_JUMP') AND jsonb_typeof(issue->'objectIds')='array','Invalid issue');PERFORM labelroom_private.review_need(jsonb_array_length(issue->'objectIds')=CASE WHEN kind='DUPLICATE' THEN 2 ELSE 1 END,'Invalid issue IDs');SELECT array_agg(id ORDER BY labelroom_private.review_utf16(id)) INTO ids FROM (SELECT labelroom_private.review_id(value) AS id FROM jsonb_array_elements(issue->'objectIds')) q;PERFORM labelroom_private.review_need(cardinality(ids)=(SELECT count(DISTINCT id) FROM unnest(ids) id),'Repeated issue ID');
 FOREACH oid IN ARRAY ids LOOP PERFORM labelroom_private.review_box(doc#>ARRAY['openlabel','frames',frame,'objects',oid,'object_data','cuboid','0','val']);END LOOP;
 FOR f IN SELECT value FROM jsonb_array_elements(p.manifest->'frames') LOOP fid:=f->>'id';boxes:='[]';FOREACH oid IN ARRAY ids LOOP occ:=doc#>ARRAY['openlabel','frames',fid,'objects',oid];IF occ IS NULL THEN boxes:=boxes||jsonb_build_array(jsonb_build_array(oid,NULL));ELSE val:=occ#>'{object_data,cuboid,0,val}';PERFORM labelroom_private.review_box(val);boxes:=boxes||jsonb_build_array(jsonb_build_array(oid,jsonb_build_array(doc#>ARRAY['openlabel','objects',oid,'type'],val)));END IF;END LOOP;tracks:=tracks||jsonb_build_array(jsonb_build_array(fid,f->'timestamp',boxes));END LOOP;
 RETURN labelroom_private.review_hash(jsonb_build_array('labelxr-issue-fingerprint/v1',p.id,p.source_hash,kind,frame,to_jsonb(ids),tracks));END $$;
CREATE FUNCTION labelroom_private.review_receipt(m public.mutations) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$ SELECT jsonb_build_object('projectId',m.project_id,'sourceBundleSha256',p.source_hash,'requestId',m.request_id,'payloadSha256',m.payload_hash,'revision',m.revision,'mutationId',m.id,'operation',m.operation,'frameId',m.frame_id,'objectId',m.object_id,'labels',v.label_doc,'reviewVerdicts',v.review_verdicts) FROM public.projects p JOIN public.label_versions v ON v.project_id=p.id AND v.revision=m.revision WHERE p.id=m.project_id $$;
CREATE FUNCTION public.commit_review(command jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE owner uuid:=auth.uid();guest boolean;p public.projects;current public.label_versions;previous public.label_versions;m public.mutations;last public.mutations;pid uuid;rid uuid;base integer;op text;fid text;oid text;partner text;why text;keys text[];expected text[];payload text;labels jsonb;verdicts jsonb;old_occ jsonb;before_v jsonb;after_v jsonb;partner_v jsonb;fp text;before_audit jsonb;after_audit jsonb;
BEGIN
 IF owner IS NULL THEN RAISE EXCEPTION 'Verified account required' USING ERRCODE='42501';END IF;SELECT is_anonymous INTO guest FROM auth.users WHERE id=owner FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Verified account required' USING ERRCODE='42501';END IF;
 PERFORM labelroom_private.review_need(jsonb_typeof(command)='object' AND octet_length(command::text)<=16384,'Bounded command required');op:=command->>'operation';expected:=ARRAY['projectId','requestId','baseRevision','operation','frameId','objectId','reason'];IF op='updateCuboid' THEN expected:=expected||ARRAY['before','after'];ELSIF op='keepIssue' THEN expected:=expected||ARRAY['before','issue','fingerprint'];ELSIF op='removeDuplicate' THEN expected:=expected||ARRAY['before','partnerId','partnerBefore','confirmed'];ELSIF op='undo' THEN expected:=expected||ARRAY['undoOf'];ELSE PERFORM labelroom_private.review_need(false,'Unknown review operation');END IF;SELECT array_agg(k ORDER BY k) INTO keys FROM jsonb_object_keys(command) k;PERFORM labelroom_private.review_need(cardinality(keys)=cardinality(expected) AND command ?& expected,'Unexpected command fields');
 PERFORM labelroom_private.review_need(jsonb_typeof(command->'projectId')='string' AND command->>'projectId' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND jsonb_typeof(command->'requestId')='string' AND command->>'requestId' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','Invalid UUID');pid:=(command->>'projectId')::uuid;rid:=(command->>'requestId')::uuid;PERFORM labelroom_private.review_need(jsonb_typeof(command->'baseRevision')='number' AND (command->>'baseRevision')::numeric BETWEEN 0 AND 300 AND (command->>'baseRevision')::numeric=trunc((command->>'baseRevision')::numeric),'Invalid base revision');base:=(command->>'baseRevision')::integer;fid:=labelroom_private.review_id(command->'frameId');oid:=labelroom_private.review_id(command->'objectId');why:=command->>'reason';PERFORM labelroom_private.review_need(why IN ('occlusion','valid-geometry','duplicate','other') AND jsonb_typeof(command->'reason')='string','Invalid reason');
 SELECT * INTO p FROM public.projects WHERE id=pid AND owner_id=owner FOR UPDATE;IF NOT FOUND OR p.status<>'ready' OR (p.kind='demo') IS DISTINCT FROM guest OR (guest AND p.expires_at<=now()) THEN RAISE EXCEPTION 'Owned live project required' USING ERRCODE='42501';END IF;payload:=labelroom_private.review_hash(jsonb_build_array('labelxr-review-command/v1',p.source_hash,command));SELECT * INTO m FROM public.mutations WHERE owner_id=owner AND request_id=rid;IF FOUND THEN PERFORM labelroom_private.review_need(m.project_id=pid AND m.payload_hash=payload AND m.revision=base+1,'Request UUID was used for another command');RETURN labelroom_private.review_receipt(m);END IF;IF p.current_revision<>base THEN RAISE EXCEPTION 'Stale review revision' USING ERRCODE='40001';END IF;IF base>=300 THEN RAISE EXCEPTION 'Review revision limit reached' USING ERRCODE='23514';END IF;
 SELECT * INTO STRICT current FROM public.label_versions WHERE project_id=pid AND revision=base;labels:=current.label_doc;verdicts:=current.review_verdicts;PERFORM labelroom_private.review_need(EXISTS(SELECT 1 FROM jsonb_array_elements(p.manifest->'frames') f WHERE f->>'id'=fid),'Unknown frame');old_occ:=labels#>ARRAY['openlabel','frames',fid,'objects',oid];before_v:=old_occ#>'{object_data,cuboid,0,val}';
 IF op='undo' THEN SELECT * INTO last FROM public.mutations WHERE project_id=pid AND revision=base;PERFORM labelroom_private.review_need(FOUND AND last.operation<>'undo' AND last.request_id::text=command->>'undoOf' AND last.request_id<>rid AND last.frame_id=fid AND last.object_id=oid AND why='other' AND jsonb_typeof(command->'undoOf')='string','Only latest committed decision may be undone once');SELECT * INTO STRICT previous FROM public.label_versions WHERE project_id=pid AND revision=base-1;labels:=previous.label_doc;verdicts:=previous.review_verdicts;before_audit:=last.after_doc;after_audit:=last.before_doc;
 ELSE PERFORM labelroom_private.review_box(before_v);PERFORM labelroom_private.review_box(command->'before');PERFORM labelroom_private.review_need(before_v=command->'before','Exact before geometry differs');
 IF op='updateCuboid' THEN after_v:=command->'after';PERFORM labelroom_private.review_box(after_v);PERFORM labelroom_private.review_need(after_v<>before_v,'Geometry update is unchanged');labels:=jsonb_set(labels,ARRAY['openlabel','frames',fid,'objects',oid,'object_data','cuboid','0','val'],after_v,false);before_audit:=before_v;after_audit:=after_v;
 ELSIF op='removeDuplicate' THEN partner:=labelroom_private.review_id(command->'partnerId');PERFORM labelroom_private.review_need(partner<>oid AND why='duplicate' AND command->'confirmed'='true'::jsonb,'Explicit different duplicate partner required');partner_v:=labels#>ARRAY['openlabel','frames',fid,'objects',partner,'object_data','cuboid','0','val'];PERFORM labelroom_private.review_box(partner_v);PERFORM labelroom_private.review_box(command->'partnerBefore');PERFORM labelroom_private.review_need(partner_v=command->'partnerBefore' AND labels#>ARRAY['openlabel','objects',oid,'type']=labels#>ARRAY['openlabel','objects',partner,'type'],'Duplicate partner geometry/class differs');PERFORM labelroom_private.review_need(labelroom_private.review_iou(before_v,partner_v)>=0.90,'Duplicate oriented IoU below 0.90');labels:=labels#-ARRAY['openlabel','frames',fid,'objects',oid];before_audit:=old_occ;after_audit:='null';
 ELSE fp:=labelroom_private.review_fingerprint(p,labels,fid,command->'issue');PERFORM labelroom_private.review_need(jsonb_typeof(command->'fingerprint')='string' AND command->>'fingerprint'=fp AND (command->'issue'->'objectIds') ? oid,'Stale issue fingerprint');before_audit:=coalesce(verdicts->fp,'null');after_audit:=jsonb_build_object('issue',command->'issue','frameId',fid,'objectId',oid,'reason',why,'revision',base+1);verdicts:=verdicts||jsonb_build_object(fp,after_audit);END IF;END IF;
 PERFORM labelroom_private.review_need(octet_length(labelroom_private.review_canonical(labels))<=2097152 AND octet_length(labelroom_private.review_canonical(verdicts))<=2097152,'Snapshot exceeds bounded JSON size');INSERT INTO public.label_versions(project_id,revision,label_doc,review_verdicts) VALUES(pid,base+1,labels,verdicts);INSERT INTO public.mutations(request_id,project_id,revision,owner_id,operation,frame_id,object_id,partner_id,before_doc,after_doc,reason,payload_hash,undo_of) VALUES(rid,pid,base+1,owner,op,fid,oid,partner,before_audit,after_audit,why,payload,CASE WHEN op='undo' THEN last.id ELSE NULL END) RETURNING * INTO m;UPDATE public.projects SET current_revision=base+1 WHERE id=pid;RETURN labelroom_private.review_receipt(m);END $$;
REVOKE ALL ON FUNCTION public.commit_review(jsonb) FROM PUBLIC,anon,service_role;GRANT EXECUTE ON FUNCTION public.commit_review(jsonb) TO authenticated;
REVOKE ALL ON FUNCTION labelroom_private.review_need(boolean,text),labelroom_private.review_utf16(text),labelroom_private.review_number(jsonb),labelroom_private.review_canonical(jsonb),labelroom_private.review_hash(jsonb),labelroom_private.review_id(jsonb),labelroom_private.review_box(jsonb),labelroom_private.review_iou(jsonb,jsonb),labelroom_private.review_fingerprint(public.projects,jsonb,text,jsonb),labelroom_private.review_receipt(public.mutations) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
